58	/**
59	 * Search box rendered on the tree canvas. The current tree always finishes
60	 * first; only then does a second, capped request look through the user's
61	 * other readable trees.
62	 */
63	export const CanvasSearch = ({
64	  members,
65	  onLocate,
66	  className,
67	  windowed = false,
68	  treeId,
69	  onFocusRoot,
70	  onOpenOtherTree,
71	}: CanvasSearchProps) => {
72	  const { t } = useTranslation(undefined, { keyPrefix: "tree-view.search" });
73	  const searchMembers = useMemberStore((s) => s.searchMembers);
74	  const searchOtherTrees = useMemberStore((s) => s.searchOtherTrees);
75	  const [query, setQuery] = useState("");
76	  const [isOpen, setIsOpen] = useState(false);
77	  const [activeIndex, setActiveIndex] = useState(0);
78	  const [serverResults, setServerResults] = useState<MemberDB[]>([]);
79	  const [otherTreeResults, setOtherTreeResults] = useState<MemberSearchHitDB[]>(
80	    [],
81	  );
82	  const [isSearchingCurrent, setIsSearchingCurrent] = useState(false);
83	  const [isSearchingOtherTrees, setIsSearchingOtherTrees] = useState(false);
84	  const containerRef = useRef<HTMLDivElement>(null);
85	  const searchRequestRef = useRef(0);
86	
87	  // Client-side results for a normally loaded tree are available immediately.
88	  const clientResults = useMemo(() => {
89	    if (windowed) return [];
90	    const normalizedQuery = query.trim().toLowerCase();
91	    if (!normalizedQuery) return [];
92	    return members
93	      .filter((member) =>
94	        getMemberSearchText(member).toLowerCase().includes(normalizedQuery),
95	      )
96	      .slice(0, MAX_CURRENT_RESULTS);
97	  }, [members, query, windowed]);
98	
99	  // A windowed tree needs a server request to complete its current-tree
100	  // results. Once that is complete (or a normal tree's local pass is ready),
101	  // start the second search for other readable trees.
102	  useEffect(() => {
103	    const normalizedQuery = query.trim();
104	    const requestId = ++searchRequestRef.current;
105	    const isCurrentRequest = () => requestId === searchRequestRef.current;
106	
107	    setOtherTreeResults([]);
108	    setIsSearchingOtherTrees(false);
109	
110	    if (!normalizedQuery) {
111	      setServerResults([]);
112	      setIsSearchingCurrent(false);
113	      return;
114	    }
115	
116	    const searchRemainingTrees = async () => {
117	      setIsSearchingOtherTrees(true);
118	      try {
119	        const results = await searchOtherTrees(
120	          normalizedQuery,
121	          treeId,
122	          MAX_RESULTS_PER_OTHER_TREE,
123	          MAX_OTHER_TREE_RESULTS,
124	        );
125	        if (isCurrentRequest()) setOtherTreeResults(results);
126	      } catch {
127	        if (isCurrentRequest()) setOtherTreeResults([]);
128	      } finally {
129	        if (isCurrentRequest()) setIsSearchingOtherTrees(false);
130	      }
131	    };
132	
133	    if (!windowed || !treeId) {
134	      setServerResults([]);
135	      setIsSearchingCurrent(false);
136	      const timer = setTimeout(() => {
137	        void searchRemainingTrees();
138	      }, SEARCH_DEBOUNCE_MS);
139	      return () => clearTimeout(timer);
140	    }
141	
142	    setIsSearchingCurrent(true);
143	    const timer = setTimeout(() => {
144	      void (async () => {
145	        try {
146	          const results = await searchMembers(
147	            treeId,
148	            normalizedQuery,
149	            MAX_CURRENT_RESULTS,
150	          );
151	          if (isCurrentRequest()) setServerResults(results);
152	        } catch {
153	          if (isCurrentRequest()) setServerResults([]);
154	        } finally {
155	          if (isCurrentRequest()) setIsSearchingCurrent(false);
156	        }
157	        if (isCurrentRequest()) await searchRemainingTrees();
158	      })();
159	    }, SEARCH_DEBOUNCE_MS);
160	    return () => clearTimeout(timer);
161	  }, [query, searchMembers, searchOtherTrees, treeId, windowed]);
162	
163	  const currentResults: CurrentSearchMember[] = windowed
164	    ? serverResults
165	    : clientResults;
166	  const otherTreeGroups = useMemo(() => {
167	    const groups = new Map<string, OtherTreeGroup>();
168	    for (const member of otherTreeResults) {
169	      const existing = groups.get(member.treeId);
170	      if (existing) {
171	        existing.members.push(member);
172	      } else {
173	        groups.set(member.treeId, {
174	          treeId: member.treeId,
175	          treeName: member.treeName,
176	          members: [member],
177	        });
178	      }
179	    }
180	    return [...groups.values()];
181	  }, [otherTreeResults]);
182	  const selectableResults = useMemo<SearchResult[]>(
183	    () => [
184	      ...currentResults.map((member) => ({ kind: "current" as const, member })),
185	      ...otherTreeResults.map((member) => ({ kind: "other" as const, member })),
186	    ],
187	    [currentResults, otherTreeResults],
188	  );
189	
190	  // Keep the active option in range whenever the result set changes.
191	  useEffect(() => setActiveIndex(0), [selectableResults]);
192	
193	  // Close the dropdown when clicking outside the search box.
194	  useEffect(() => {
195	    if (!isOpen) return;
196	    const onPointerDown = (event: PointerEvent) => {
197	      if (!containerRef.current?.contains(event.target as globalThis.Node)) {
198	        setIsOpen(false);
199	      }
200	    };
201	    document.addEventListener("pointerdown", onPointerDown);
202	    return () => document.removeEventListener("pointerdown", onPointerDown);
203	  }, [isOpen]);
204	
205	  const selectCurrent = (member: CurrentSearchMember) => {
206	    if (windowed) {
207	      onFocusRoot?.(member.id);
208	      setQuery("");
209	      setIsOpen(false);
210	      return;
211	    }
212	    onLocate(member as Member);
213	    setIsOpen(false);
214	  };
215	
216	  const selectOtherTree = async (member: MemberSearchHitDB) => {
217	    try {
218	      await onOpenOtherTree(member.treeId, member.id);
219	      setQuery("");
220	      setIsOpen(false);
221	    } catch {
222	      toast.error(t("open-error"));
223	    }
224	  };
225	
226	  const selectResult = (result: SearchResult) => {
227	    if (result.kind === "other") {
228	      void selectOtherTree(result.member);
229	      return;
230	    }
231	    selectCurrent(result.member);
232	  };
233	
234	  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
235	    event.stopPropagation();
236	    if (!selectableResults.length) return;
237	    if (event.key === "ArrowDown") {
238	      event.preventDefault();
239	      setActiveIndex((index) => (index + 1) % selectableResults.length);
240	    } else if (event.key === "ArrowUp") {
241	      event.preventDefault();
242	      setActiveIndex(
243	        (index) =>
244	          (index - 1 + selectableResults.length) % selectableResults.length,
245	      );
246	    } else if (event.key === "Enter") {
247	      event.preventDefault();
248	      const result = selectableResults[activeIndex];
249	      if (result) selectResult(result);
250	    } else if (event.key === "Escape") {
251	      setIsOpen(false);
252	    }
253	  };
254	
255	  const showResults = isOpen && query.trim().length > 0;
256	  const hasOtherTreeSection =
257	    isSearchingOtherTrees || otherTreeGroups.length > 0;
258	  const hasNoResults =
259	    !isSearchingCurrent &&
260	    !isSearchingOtherTrees &&
261	    selectableResults.length === 0;
262	
263	  const renderMemberResult = (
264	    member: CurrentSearchMember | MemberSearchHitDB,
265	    index: number,
266	    kind: SearchResult["kind"],
267	  ) => {
268	    const name = memberName(member) || t("unnamed");
269	    const sublabel = formatMemberSubLabel(
270	      member.maidenName,
271	      memberBirthDate(member),
272	      (maidenName) => t("nee", { name: maidenName }),
273	    );
274	    const isOtherTree = kind === "other";
275	    const treeName = isOtherTree ? (member as MemberSearchHitDB).treeName : "";
276	
277	    return (
278	      <li
279	        key={
280	          isOtherTree
281	            ? `${(member as MemberSearchHitDB).treeId}:${member.id}`
282	            : member.id
283	        }
284	      >
285	        <button
286	          type="button"
287	          className={`flex w-full items-start gap-2 px-3 py-2 text-left text-sm hover:bg-accent hover:text-accent-foreground ${
288	            index === activeIndex ? "bg-accent text-accent-foreground" : ""
289	          }`}
290	          onPointerEnter={() => setActiveIndex(index)}
291	          onClick={() =>
292	            selectResult(
293	              isOtherTree
294	                ? { kind: "other", member: member as MemberSearchHitDB }
295	                : { kind: "current", member: member as CurrentSearchMember },
296	            )
297	          }
298	          aria-label={
299	            isOtherTree
300	              ? t("open-other-tree", { tree: treeName, member: name })
301	              : undefined
302	          }
303	        >
304	          <span className="flex min-w-0 flex-1 flex-col items-start">
305	            <span className="font-medium">{name}</span>
306	            {sublabel && (
307	              <span className="text-xs text-muted-foreground">{sublabel}</span>
308	            )}
309	          </span>
310	          {isOtherTree && (
311	            <ArrowUpRight
312	              className="mt-0.5 size-4 shrink-0 text-muted-foreground"
313	              aria-hidden="true"
314	            />
315	          )}
316	        </button>
317	      </li>
318	    );
319	  };
320	
321	  let otherTreeIndex = currentResults.length;
322	
323	  return (
324	    <div ref={containerRef} className={cn("w-64", className)}>
325	      <div className="relative">
326	        <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground pointer-events-none" />
327	        <Input
328	          value={query}
329	          placeholder={t("placeholder")}
330	          onChange={(event) => {
331	            setQuery(event.target.value);
332	            setIsOpen(true);
333	          }}
334	          onFocus={() => setIsOpen(true)}
335	          onKeyDown={onKeyDown}
336	          className="pl-8 pr-8 bg-background shadow-md"
337	        />
338	        {query && (
339	          <Button
340	            variant="ghost"
341	            size="icon-sm"
342	            className="absolute right-1 top-1/2 -translate-y-1/2"
343	            onClick={() => {
344	              setQuery("");
345	              setIsOpen(false);
346	            }}
347	            aria-label={t("clear")}
348	          >
349	            <X className="h-4 w-4" />
350	          </Button>
351	        )}
352	      </div>
353	
354	      {showResults && (
355	        <ul className="mt-1 max-h-80 overflow-auto rounded-md border bg-popover text-popover-foreground shadow-md">
356	          {isSearchingCurrent ? (
357	            <li className="px-3 py-2 text-sm text-muted-foreground">
358	              {t("searching")}
359	            </li>
360	          ) : (
361	            currentResults.length > 0 && (
362	              <>
363	                {hasOtherTreeSection && (
364	                  <li className="px-3 pb-1 pt-2 text-xs font-medium text-muted-foreground">
365	                    {t("current-tree")}
366	                  </li>
367	                )}
368	                {currentResults.map((member, index) =>
369	                  renderMemberResult(member, index, "current"),
370	                )}
371	              </>
372	            )
373	          )}
374	
375	          {hasOtherTreeSection && (
376	            <li className="border-t">
377	              <div className="px-3 pb-1 pt-2 text-xs font-medium text-muted-foreground">
378	                {t("other-trees")}
379	              </div>
380	              {isSearchingOtherTrees ? (
381	                <div className="px-3 py-2 text-sm text-muted-foreground">
382	                  {t("other-trees-searching")}
383	                </div>
384	              ) : (
385	                <ul>
386	                  {otherTreeGroups.map((group) => (
387	                    <li key={group.treeId}>
388	                      <div className="px-3 pb-1 pt-2 text-xs text-muted-foreground">
389	                        {group.treeName}
390	                      </div>
391	                      <ul>
392	                        {group.members.map((member) => {
393	                          const index = otherTreeIndex;
394	                          otherTreeIndex += 1;
395	                          return renderMemberResult(member, index, "other");
396	                        })}
397	                      </ul>
398	                    </li>
399	                  ))}
400	                </ul>
401	              )}
402	            </li>
403	          )}
404	
405	          {hasNoResults && (
406	            <li className="px-3 py-2 text-sm text-muted-foreground">
407	              {t("no-results")}
408	            </li>
409	          )}
