50	  if (tokens.length <= 1) {
51	    return searchText.includes(trimmed.toLowerCase());
52	  }
53	  return tokens.every((token) => {
54	    const lower = token.toLowerCase();
55	    if (searchText.includes(lower)) return true;
56	    if (!YEAR_TOKEN.test(token)) return false;
