69	export function formatMemberSubLabel(
70	  maidenName: string | null | undefined,
71	  birthDate: string | null | undefined,
72	  formatMaiden: (name: string) => string,
73	): string | undefined {
74	  // Parse the year inline rather than importing dateUtils: this module is
75	  // pulled into the tree-layout web worker (via memberMapping), and dateUtils
76	  // imports i18n, which touches localStorage and crashes the worker.
77	  const yearMatch = birthDate?.match(/^(\d{4})/);
78	  const parts = [
79	    maidenName ? formatMaiden(maidenName) : null,
80	    yearMatch ? yearMatch[1] : null,
81	  ].filter(Boolean) as string[];
82	  return parts.length ? parts.join(" · ") : undefined;
83	}
