97	export interface ParentSlots {
98	  paternalParent: string | null;
99	  maternalParent: string | null;
100	}
101	
102	/**
103	 * Resolve a member's (up to two) parent slots from their "parent" relations.
104	 *
105	 * A gendered parent claims its natural slot first (male → paternal, female →
106	 * maternal); any leftover parent — one with unknown gender, or a second parent
107	 * of the same gender — then fills whichever slot is still free. Running the
108	 * gendered pass first makes the result independent of the order relations come
109	 * back from the API and stops a later gendered parent from evicting one that
110	 * was tentatively placed.
111	 */
112	export function reconstructParents(
113	  parentRelations: { to_member_id: string }[],
114	  genderById: Map<string, string>,
115	): ParentSlots {
116	  const slots: ParentSlots = { paternalParent: null, maternalParent: null };
117	
118	  for (const r of parentRelations) {
119	    const gender = genderById.get(r.to_member_id);
120	    if (gender === "m" && !slots.paternalParent) {
121	      slots.paternalParent = r.to_member_id;
122	    } else if (gender === "f" && !slots.maternalParent) {
123	      slots.maternalParent = r.to_member_id;
124	    }
125	  }
126	
127	  for (const r of parentRelations) {
128	    const id = r.to_member_id;
129	    if (id === slots.paternalParent || id === slots.maternalParent) continue;
130	    if (!slots.paternalParent) slots.paternalParent = id;
131	    else if (!slots.maternalParent) slots.maternalParent = id;
132	    // More than two parents can't be represented; the rest are ignored.
133	  }
134	
135	  return slots;
136	}

